    if ((o.kind !== "window" && o.kind !== "door") || !inHouse(o)) continue;
    for (const [x, y, z, block] of frameCells(o)) {
      if (y > eave || isOpening(x, y, z)) continue;
      g.set(x, y, z, block);
    }
  }

